sys_script.script:
(function executeRule(current, previous /* null when async */) {

    // Validate Expected Discharge Date
    if (!current.admission_date.nil() && !current.expected_discharge_date.nil()) {

        var admissionDate = new GlideDateTime(current.admission_date);
        var expectedDischargeDate = new GlideDateTime(current.expected_discharge_date);

        if (expectedDischargeDate.before(admissionDate)) {
            gs.addErrorMessage('Expected Discharge Date cannot be before Admission Date.');
            current.setAbortAction(true);
            return;
        }
    }

    // Validate Discharge Date
    if (!current.admission_date.nil() && !current.discharge_date.nil()) {

        var admissionDate2 = new GlideDateTime(current.admission_date);
        var dischargeDate = new GlideDateTime(current.discharge_date);

        if (dischargeDate.before(admissionDate2)) {
            gs.addErrorMessage('Discharge Date cannot be before Admission Date.');
            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
